114	pub(crate) fn parse_operation_definition(p: &mut GraphqlParser) -> ParsedSyntax {
115	    if !is_at_operation(p) {
116	        return Absent;
117	    }
118	
119	    if is_at_selection_set(p) {
120	        return parse_selection_set(p);
121	    }
122	
123	    let m = p.start();
124	    {
125	        let m = p.start();
126	        p.bump_ts(OPERATION_TYPE);
127	        m.complete(p, GRAPHQL_OPERATION_TYPE);
128	    }
129	
130	    // we don't need diagnostic here, because name is optional
131	    parse_name(p).ok();
132	    // we don't need diagnostic here, because variable definitions are optional
133	    parse_variable_definitions(p).ok();
134	
135	    DirectiveList.parse_list(p);
136	    parse_selection_set(p).ok();
137	
138	    Present(m.complete(p, GRAPHQL_OPERATION_DEFINITION))
139	}
