219	#[inline]
220	fn parse_variable_definitions(p: &mut GraphqlParser) -> ParsedSyntax {
221	    if !p.at(T!['(']) {
222	        return Absent;
223	    }
224	
225	    let m = p.start();
226	
227	    p.bump(T!['(']);
228	    VariableDefinitionList.parse_list(p);
229	    p.expect(T![')']);
230	
231	    Present(m.complete(p, GRAPHQL_VARIABLE_DEFINITIONS))
232	}
