122	    }
123	    // handle typo in operation type
124	    else {
125	        p.error(expected_operation_type(p, p.cur_range()));
126	        p.bump_any();
127	    }
128	    p.expect(T![:]);
129	    parse_named_type(p).or_add_diagnostic(p, expected_named_type);
