pub(crate) fn is_at_argument_list_end(p: &mut GraphqlParser<'_>) -> bool {
    p.at(T![')'])
    // also handle the start of a selection set
    || is_at_selection_set_end(p)
    // at the start of a new directive
    || is_at_directive(p)
}
