+pub(crate) fn parse_root(p: &mut GraphqlParser) -> CompletedMarker {
+    let m = p.start();
+
+    p.eat(UNICODE_BOM);
+
+    DefinitionList.parse_list(p);
+
+    p.expect(EOF);
+
+    m.complete(p, GRAPHQL_ROOT)
+}
